counts = {}
for language in ["Scratch", "C", "C", "Python", "C", "Scratch", "C"]:
    if language in counts:
        counts[language] += 1
    else:
        counts[language] = 1
for language in sorted(counts, key=counts.get, reverse=True):
    print(f"{language}: {counts[language]}")

